{
    "investigate": [
        {
            "tool": "logs",
            "service": "invoice-agent",
            "level": "ERROR",
            "contains": "database timeout: connection pool exhausted",
            "why": "Check if invoice-agent is also experiencing database connection exhaustion, which would indicate the database is the root cause rather than a specific service"
        },
        {
            "tool": "sql",
            "query": "SELECT service, COUNT(*) as open_connections FROM db_sessions WHERE open = 1 GROUP BY service ORDER BY open_connections DESC",
            "why": "Identify which services are holding the most database connections to understand connection pool exhaustion pattern"
        }
    ],
    "hypotheses": [
        {
            "service": "database",
            "kind": "resource_exhaustion",
            "mechanism": "Database connection pool exhausted due to excessive connections from multiple services, causing timeouts and cascading failures",
            "supporting": ["E2", "E4", "E6", "E8", "E13", "E17", "E18", "E19", "E20"],
            "refuting": [],
            "explains": ["M2_error_burst", "M3_dead_letters", "M4_db_pool_pressure"],
            "repair_plan": [
                {
                    "action": "restart_service",
                    "params": {
                        "service": "database"
                    }
                }
            ]
        }
    ],
    "summary": "Database connection pool exhaustion is causing widespread timeouts and failures across multiple services that depend on it"
